                Complex z = x.get(i);
                x.set(i, z.divide(n));
            }

static int reverseBits(int num, int log2n) {
        int reversed = 0;
        for (int i = 0; i < log2n; i++) {
            if ((num & (1 << i)) != 0) {
                reversed |= 1 << (log2n - 1 - i);
            }

static void paddingPowerOfTwo(Collection<Complex> x) {
